from __future__ import annotations

from typing import Any


def route(value: Any, outcome: str, rationale: str, source: str, locator: str, *, operator: str = "equals") -> dict[str, Any]:
    return {"operator": operator, "value": value, "outcome": outcome, "rationale": rationale, "source": source, "locator": locator}


def decision(key: str, title: str, input_name: str, input_description: str, routes: list[dict[str, Any]], *, producer: str = "prior-task") -> dict[str, Any]:
    return {"key": key, "title": title, "input": {"name": input_name, "description": input_description, "producer": producer}, "routes": routes}


